set-variable.value:
#[output application/java
var raw = if (payload is String or payload is Binary) read(payload, 'application/json') else (payload default {})
var body = raw.payload default raw
var addr = body.shippingAddress default raw.shippingAddress default {}
---
raw ++ {
    correlationId: raw.correlationId default correlationId,
    sagaId: raw.sagaId default ('SAGA-' ++ (uuid() as String)),
    stepId: raw.stepId default ('STEP-' ++ (uuid() as String)),
    orderId: raw.orderId default body.orderId,
    shippingAddress: {
        addressLine1: addr.addressLine1 default body.addressLine1 default raw.addressLine1,
        city: addr.city default body.city default raw.city,
        state: addr.state default body.state default raw.state default '',
        postalCode: addr.postalCode default body.postalCode default raw.postalCode,
        country: addr.country default body.country default raw.country
    },
    serviceLevel: raw.serviceLevel default body.serviceLevel default 'STANDARD'
}]

#[output application/java ---
{
	correlationId: vars.request.correlationId,
	sagaId: vars.request.sagaId,
	stepId: vars.request.stepId,
	stepName: vars.request.stepName default 'CANCEL_SHIPPING',
	attempt: vars.request.attempt default 1,
	payload: {
		shippingId: vars.request.shippingId default null,
		orderId: vars.request.orderId default null
	}
}]

#[output application/java
var raw = if (payload is String or payload is Binary) read(payload, 'application/json') else (payload default {})
var body = raw.payload default raw
var addr = body.shippingAddress default raw.shippingAddress default {}
---
raw ++ {
    correlationId: raw.correlationId default correlationId,
    sagaId: raw.sagaId default 'SAGA-UNKNOWN',
    stepId: raw.stepId default 'STEP-UNKNOWN',
    replyTo: raw.replyTo default 'shipping.dispatch.reply',
    orderId: raw.orderId default body.orderId,
    shippingAddress: {
        addressLine1: addr.addressLine1 default body.addressLine1 default raw.addressLine1,
        city: addr.city default body.city default raw.city,
        state: addr.state default body.state default raw.state default '',
        postalCode: addr.postalCode default body.postalCode default raw.postalCode,
        country: addr.country default body.country default raw.country
    },
    serviceLevel: raw.serviceLevel default body.serviceLevel default 'STANDARD'
}]

#[output application/java ---
{
	correlationId: vars.request.correlationId,
	sagaId: vars.request.sagaId,
	stepId: vars.request.stepId,
	stepName: vars.request.stepName default 'CANCEL_SHIPPING',
	attempt: vars.request.attempt default 1,
	payload: {
		shippingId: vars.request.shippingId default null,
		orderId: vars.request.orderId default null
	}
}]

